macro_rules! Change {
    () => {
        # [doc = " How an index entry needs to be changed to obtain the destination worktree state, i.e. `entry.apply(this_change) == worktree-entry`."] # [derive (Clone , PartialEq , Eq , PartialOrd , Ord , Debug)] pub enum Change < T = () , U = () > { # [doc = " This corresponding file does not exist in the worktree anymore."] Removed , # [doc = " The type of file changed compared to the worktree."] # [doc = ""] # [doc = " Examples include when a symlink is now a regular file, or a regular file was replaced with a named pipe."] # [doc = ""] # [doc = " ### Deviation"] # [doc = ""] # [doc = " A change to a non-file is marked as `modification` in Git, but that's related to the content which we can't evaluate."] # [doc = " Hence, a type-change is considered more appropriate."] Type { # [doc = " The mode the worktree file would have if it was added to the index, and the mode that differs compared"] # [doc = " to what's currently stored in the index."] worktree_mode : gix_index :: entry :: Mode , } , # [doc = " This worktree file was modified in some form, like a permission change or content change or both,"] # [doc = " as compared to this entry."] Modification { # [doc = " Indicates that one of the stat changes was an executable bit change"] # [doc = " which is a significant change itself."] executable_bit_changed : bool , # [doc = " The output of the [`CompareBlobs`](crate::index_as_worktree::traits::CompareBlobs) run on this entry."] # [doc = " If there is no content change and only the executable bit"] # [doc = " changed then this is `None`."] content_change : Option < T > , # [doc = " If true, the caller is expected to set [entry.stat.size = 0](gix_index::entry::Stat::size) to assure this"] # [doc = " otherwise racily clean entry can still be detected as dirty next time this is called, but this time without"] # [doc = " reading it from disk to hash it. It's a performance optimization and not doing so won't change the correctness"] # [doc = " of the operation."] set_entry_stat_size_zero : bool , } , # [doc = " A submodule is initialized and checked out, and there was modification to either:"] # [doc = ""] # [doc = " * the `HEAD` as compared to the superproject's desired commit for `HEAD`"] # [doc = " * the worktree has at least one modified file"] # [doc = " * there is at least one untracked file"] # [doc = ""] # [doc = " The exact nature of the modification is handled by the caller which may retain information per submodule or"] # [doc = " re-compute details as needed when seeing this variant."] SubmoduleModification (U) , }
    };
}

Change!();